ruleHooks.extraMethods:
; Carregar os itens dos documentos na global de trabalho
; linha = tipo^documento^item^descrição^qtde^qtdeEtiquetas^controle^produto
;
; set sc=$$CarregarDocumentos^WDOMTESTEPMP110RG(term,codEmpresa,tipo,documento,controle,dataInicial,dataFinal)
CarregarDocumentos(term,codEmpresa,tipo,documento,controle,dataInicial,dataFinal)	;
$$$VAR
new sc,seq
;
if $get(tipo)="" quit $$$ERROR(10000,"Tipo de Documento: Campo obrigatório!")
if $get(documento)="",$get(controle)="",($get(dataInicial)=""!($get(dataFinal)="")) quit $$$ERROR(10000,"Informe o Documento, o Controle ou o período!")
;
set sc=$$$OK,seq=0
if tipo="PC" set sc=$$CarregarPedidoCompra(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
if tipo="PV" set sc=$$CarregarPedidoVenda(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
if tipo="NFE" set sc=$$CarregarNotaEntrada(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
if tipo="NFS" set sc=$$CarregarNotaSaida(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
if tipo="OF" set sc=$$CarregarOrdemFabricacao(term,codEmpresa,documento,controle,dataInicial,dataFinal,.seq)
if tipo="OR" set sc=$$CarregarOrdemRetrabalho(term,codEmpresa,documento,controle,dataInicial,dataFinal,.seq)
;
quit sc
;
; Data dentro do período informado (período vazio = qualquer data)
;
; if $$DentroPeriodo^WDOMTESTEPMP110RG(data,dataInicial,dataFinal)
DentroPeriodo(data,dataInicial,dataFinal)	;
$$$VAR
;
set data=$piece($piece($get(data),";"),",")
if $get(dataInicial)'="",(data=""!(data<dataInicial)) quit 0
if $get(dataFinal)'="",(data=""!(data>dataFinal)) quit 0
;
quit 1
;
; Incluir um item na global de trabalho (sugere 1 etiqueta com a quantidade total)
;
; set sc=$$IncluirItem^WDOMTESTEPMP110RG(term,codEmpresa,tipo,documento,item,codProduto,quantidade,controle,.seq)
IncluirItem(term,codEmpresa,tipo,documento,item,codProduto,quantidade,controle,seq)	;
$$$VAR
new sc,cgigen,linha
;
set sc=$$VerItemCGIGEN^CCCGIRG001(codEmpresa,codProduto,.cgigen)
set seq=seq+1
set linha=tipo_Z_documento_Z_item_Z_codProduto_" - "_$piece($get(cgigen),Z,1)
set linha=linha_Z_+quantidade_Z_1_Z_$get(controle)_Z_codProduto
;
quit $$GravarGlobalTrabalho(term,seq,linha)
;
; Quantidade por etiqueta = quantidade do item / quantidade de etiquetas
;
; set qtde=$$QtdePorEtiqueta^WDOMTESTEPMP110RG(quantidade,qtdEtiquetas)
QtdePorEtiqueta(quantidade,qtdEtiquetas)	;
$$$VAR
;
if +$get(qtdEtiquetas)<1 quit ""
;
quit +$fnumber(+$get(quantidade)/qtdEtiquetas,"",3)
;
; PC - Pedido de Compra: ^ESSPDC(emp,ped) capa (2 emissão); itens (1 produto, 2 quantidade x1000)
;
; set sc=$$CarregarPedidoCompra^WDOMTESTEPMP110RG(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
CarregarPedidoCompra(term,codEmpresa,documento,dataInicial,dataFinal,seq)	;
$$$VAR
new sc,codPedido
;
if $get(documento)'="" quit $$CarregarItensPedidoCompra(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
;
set sc=$$$OK,codPedido=""
for  set codPedido=$order(^ESSPDC(codEmpresa,codPedido)) quit:codPedido=""!$$$ISERR(sc)  do
. set sc=$$CarregarItensPedidoCompra(term,codEmpresa,codPedido,dataInicial,dataFinal,.seq)
;
quit sc
;
CarregarItensPedidoCompra(term,codEmpresa,codPedido,dataInicial,dataFinal,seq)	;
$$$VAR
new sc,esspdc,item,esspdci
;
set esspdc=$get(^ESSPDC(codEmpresa,codPedido))
if esspdc="" quit $$$OK
if '$$DentroPeriodo($piece(esspdc,Z,2),dataInicial,dataFinal) quit $$$OK
;
set sc=$$$OK,item=""
for  set item=$order(^ESSPDC(codEmpresa,codPedido,item)) quit:item=""!$$$ISERR(sc)  do
. quit:item'=+item
. set esspdci=$get(^ESSPDC(codEmpresa,codPedido,item))
. quit:$piece(esspdci,Z,1)=""
. set sc=$$IncluirItem(term,codEmpresa,"PC",codPedido,item,$piece(esspdci,Z,1),$piece(esspdci,Z,2)/1000,"",.seq)
;
quit sc
;
; PV - Pedido de Venda: ^PVPD(emp,ped) capa; ^PVBPDD(emp,dataDigitação,ped) por período
;
; set sc=$$CarregarPedidoVenda^WDOMTESTEPMP110RG(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
CarregarPedidoVenda(term,codEmpresa,documento,dataInicial,dataFinal,seq)	;
$$$VAR
new sc,data,codPedido
;
if $get(documento)'="" quit $$CarregarItensPedidoVenda(term,codEmpresa,documento,.seq)
;
set sc=$$$OK,data=dataInicial-1
for  set data=$order(^PVBPDD(codEmpresa,data)) quit:data=""!(data>dataFinal)!$$$ISERR(sc)  do
. set codPedido=""
. for  set codPedido=$order(^PVBPDD(codEmpresa,data,codPedido)) quit:codPedido=""!$$$ISERR(sc)  do
. . set sc=$$CarregarItensPedidoVenda(term,codEmpresa,codPedido,.seq)
;
quit sc
;
CarregarItensPedidoVenda(term,codEmpresa,codPedido,seq)	;
$$$VAR
new sc,pvpd,item
;
set sc=$$VerPedido^CCPVRG001(codEmpresa,codPedido,,.pvpd)
if $$$ISERR(sc) quit sc
;
set item=""
for  set item=$order(^PVPD(codEmpresa,codPedido,item)) quit:item=""!$$$ISERR(sc)  do
. quit:item'=+item
. set sc=$$VerPedido^CCPVRG001(codEmpresa,codPedido,item,.pvpd)
. quit:$$$ISERR(sc)!($piece(pvpd,Z,1)="")
. set sc=$$IncluirItem(term,codEmpresa,"PV",codPedido,item,$piece(pvpd,Z,1),$piece(pvpd,Z,2)/1000,"",.seq)
;
quit sc
;
; NFE - Nota Fiscal de Entrada: ^ESENFE(emp,dataEntrada,fornecedor,série,nota[,item])
;
; set sc=$$CarregarNotaEntrada^WDOMTESTEPMP110RG(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
CarregarNotaEntrada(term,codEmpresa,documento,dataInicial,dataFinal,seq)	;
$$$VAR
new sc,data,codFornecedor,codSerie,codNota,item,esenfei
;
set sc=$$$OK,data=$select($get(dataInicial)'="":dataInicial-1,1:"")
for  set data=$order(^ESENFE(codEmpresa,data)) quit:data=""!($get(dataFinal)'=""&(data>dataFinal))!$$$ISERR(sc)  do
. set codFornecedor=""
. for  set codFornecedor=$order(^ESENFE(codEmpresa,data,codFornecedor)) quit:codFornecedor=""!$$$ISERR(sc)  do
. . set codSerie=""
. . for  set codSerie=$order(^ESENFE(codEmpresa,data,codFornecedor,codSerie)) quit:codSerie=""!$$$ISERR(sc)  do
. . . set codNota=""
. . . for  set codNota=$order(^ESENFE(codEmpresa,data,codFornecedor,codSerie,codNota)) quit:codNota=""!$$$ISERR(sc)  do
. . . . quit:$get(documento)'=""&(codNota'=documento)
. . . . set item=""
. . . . for  set item=$order(^ESENFE(codEmpresa,data,codFornecedor,codSerie,codNota,item)) quit:item=""!$$$ISERR(sc)  do
. . . . . quit:item'=+item
. . . . . set esenfei=$get(^ESENFE(codEmpresa,data,codFornecedor,codSerie,codNota,item))
. . . . . quit:$piece(esenfei,Z,1)=""
. . . . . set sc=$$IncluirItem(term,codEmpresa,"NFE",codNota,item,$piece(esenfei,Z,1),$piece(esenfei,Z,2)/1000,"",.seq)
;
quit sc
;
; NFS - Nota Fiscal de Saída: ^FTNF(emp,dataEmissão,nota[,item])
;
; set sc=$$CarregarNotaSaida^WDOMTESTEPMP110RG(term,codEmpresa,documento,dataInicial,dataFinal,.seq)
CarregarNotaSaida(term,codEmpresa,documento,dataInicial,dataFinal,seq)	;
$$$VAR
new sc,data,codNota,item,ftnfi
;
set sc=$$$OK,data=$select($get(dataInicial)'="":dataInicial-1,1:"")
for  set data=$order(^FTNF(codEmpresa,data)) quit:data=""!($get(dataFinal)'=""&(data>dataFinal))!$$$ISERR(sc)  do
. set codNota=""
. for  set codNota=$order(^FTNF(codEmpresa,data,codNota)) quit:codNota=""!$$$ISERR(sc)  do
. . quit:$get(documento)'=""&(codNota'=documento)
. . set item=""
. . for  set item=$order(^FTNF(codEmpresa,data,codNota,item)) quit:item=""!$$$ISERR(sc)  do
. . . quit:item'=+item
. . . set sc=$$VerNotaFiscal^CCFTRG001(codEmpresa,data,codNota,item,.ftnfi)
. . . quit:$$$ISERR(sc)!($piece(ftnfi,Z,1)="")
. . . set sc=$$IncluirItem(term,codEmpresa,"NFS",codNota,item,$piece(ftnfi,Z,1),$piece(ftnfi,Z,2)/1000,"",.seq)
;
quit sc
;
; OF - Ordem de Fabricação: ^PMPORF(emp,of) (1 início, 3 engenharia, 4 programada, 14 controle)
; Por controle: ^PMPCOF(emp,controle,of); por período: ^PMPOFD(emp,dataInício,of)
;
; set sc=$$CarregarOrdemFabricacao^WDOMTESTEPMP110RG(term,codEmpresa,documento,controle,dataInicial,dataFinal,.seq)
CarregarOrdemFabricacao(term,codEmpresa,documento,controle,dataInicial,dataFinal,seq)	;
$$$VAR
new sc,codOF,data
;
if $get(documento)'="" quit $$IncluirOrdemFabricacao(term,codEmpresa,documento,.seq)
;
set sc=$$$OK,codOF=""
if $get(controle)'="" do  quit sc
. for  set codOF=$order(^PMPCOF(codEmpresa,controle,codOF)) quit:codOF=""!$$$ISERR(sc)  do
. . set sc=$$IncluirOrdemFabricacao(term,codEmpresa,codOF,.seq)
;
set data=dataInicial-1
for  set data=$order(^PMPOFD(codEmpresa,data)) quit:data=""!(data>dataFinal)!$$$ISERR(sc)  do
. set codOF=""
. for  set codOF=$order(^PMPOFD(codEmpresa,data,codOF)) quit:codOF=""!$$$ISERR(sc)  do
. . set sc=$$IncluirOrdemFabricacao(term,codEmpresa,codOF,.seq)
;
quit sc
;
IncluirOrdemFabricacao(term,codEmpresa,codOF,seq)	;
$$$VAR
new sc,pmporf,decimais,diviso
;
set sc=$$VerOF^CCPMPRG001(codEmpresa,codOF,.pmporf)
if $$$ISERR(sc) quit sc
set sc=$$VerNumeroDecimaisOF^CCPGARG001(codEmpresa,.decimais,.diviso)
if $$$ISERR(sc) quit sc
;
quit $$IncluirItem(term,codEmpresa,"OF",codOF,1,$$ObterCodItem^CCCGIRG003(codEmpresa,$piece(pmporf,Z,3)),$piece(pmporf,Z,4)/diviso,$piece(pmporf,Z,14),.seq)
;
; OR - Ordem de Retrabalho: ^PMRORR(emp,or) (1 controle, 2 início, 6 engenharia, 7 a recuperar)
; Por controle: ^PMRORC(emp,controle,or); por período: ^PMRORD(emp,dataInício,or)
;
; set sc=$$CarregarOrdemRetrabalho^WDOMTESTEPMP110RG(term,codEmpresa,documento,controle,dataInicial,dataFinal,.seq)
CarregarOrdemRetrabalho(term,codEmpresa,documento,controle,dataInicial,dataFinal,seq)	;
$$$VAR
new sc,codOR,data
;
if $get(documento)'="" quit $$IncluirOrdemRetrabalho(term,codEmpresa,documento,.seq)
;
set sc=$$$OK,codOR=""
if $get(controle)'="" do  quit sc
. for  set codOR=$order(^PMRORC(codEmpresa,controle,codOR)) quit:codOR=""!$$$ISERR(sc)  do
. . set sc=$$IncluirOrdemRetrabalho(term,codEmpresa,codOR,.seq)
;
set data=dataInicial-1
for  set data=$order(^PMRORD(codEmpresa,data)) quit:data=""!(data>dataFinal)!$$$ISERR(sc)  do
. set codOR=""
. for  set codOR=$order(^PMRORD(codEmpresa,data,codOR)) quit:codOR=""!$$$ISERR(sc)  do
. . set sc=$$IncluirOrdemRetrabalho(term,codEmpresa,codOR,.seq)
;
quit sc
;
IncluirOrdemRetrabalho(term,codEmpresa,codOR,seq)	;
$$$VAR
new sc,pmrorr,decimais,diviso
;
set sc=$$VerOR^CCPMRRG001(codEmpresa,codOR,.pmrorr)
if $$$ISERR(sc) quit sc
set sc=$$VerNumeroDecimaisOF^CCPGARG001(codEmpresa,.decimais,.diviso)
if $$$ISERR(sc) quit sc
;
quit $$IncluirItem(term,codEmpresa,"OR",codOR,1,$$ObterCodItem^CCCGIRG003(codEmpresa,$piece(pmrorr,Z,6)),$piece(pmrorr,Z,7)/diviso,$piece(pmrorr,Z,1),.seq)
;
; Validar o documento informado conforme o tipo
;
; set sc=$$ValidarDocumento^WDOMTESTEPMP110RG(codEmpresa,tipo,documento)
ValidarDocumento(codEmpresa,tipo,documento)	;
$$$VAR
new sc,dados
;
if $get(documento)="" quit $$$OK
if tipo="PC",'$data(^ESSPDC(codEmpresa,documento)) quit $$$ERROR(10000,"Pedido de compra "_documento_" não cadastrado!")
if tipo="PV" quit $$VerPedido^CCPVRG001(codEmpresa,documento,,.dados)
if tipo="OF" quit $$VerOF^CCPMPRG001(codEmpresa,documento,.dados)
if tipo="OR" quit $$VerOR^CCPMRRG001(codEmpresa,documento,.dados)
;
quit $$$OK
;
; Validar o controle (OF: ^PMPCOF/^PMPOBC; OR: ^PMRORC)
;
; set sc=$$ValidarControle^WDOMTESTEPMP110RG(codEmpresa,tipo,controle)
ValidarControle(codEmpresa,tipo,controle)	;
$$$VAR
;
if $get(controle)="" quit $$$OK
if tipo="OF",'$data(^PMPCOF(codEmpresa,controle)),'$data(^PMPOBC(codEmpresa,controle)) quit $$$ERROR(10000,"Controle "_controle_" sem ordens de fabricação!")
if tipo="OR",'$data(^PMRORC(codEmpresa,controle)) quit $$$ERROR(10000,"Controle "_controle_" sem ordens de retrabalho!")
;
quit $$$OK
;
; F7 do Documento: documentos do tipo no período (tabela(documento)=descrição)
;
; set sc=$$ObterDocumentosF7^WDOMTESTEPMP110RG(codEmpresa,tipo,dataInicial,dataFinal,.tabela)
ObterDocumentosF7(codEmpresa,tipo,dataInicial,dataFinal,tabela)	;
$$$VAR
new sc,term,seq,linha,quantidade
;
kill tabela
if $get(tipo)="" quit $$$ERROR(10000,"Informe o Tipo de Documento!")
if $get(dataInicial)=""!($get(dataFinal)="") quit $$$ERROR(10000,"Informe o período para consultar os documentos!")
;
set term=$job_"F7"
kill ^mtempWDOMTESTEPMP110(term)
set sc=$$CarregarDocumentos(term,codEmpresa,tipo,"","",dataInicial,dataFinal)
set seq=""
for  set seq=$order(^mtempWDOMTESTEPMP110(term,seq)) quit:seq=""  do
. set linha=^mtempWDOMTESTEPMP110(term,seq)
. set quantidade=$get(tabela($piece(linha,Z,2)))+1
. set tabela($piece(linha,Z,2))=quantidade_" item(ns)"
kill ^mtempWDOMTESTEPMP110(term)
;
quit sc
;
; Imprimir as etiquetas das linhas marcadas (lote pelo PrintTagList)
;
; set sc=$$ImprimirEtiquetas^WDOMTESTEPMP110RG(term,codEmpresa)
ImprimirEtiquetas(term,codEmpresa)	;
$$$VAR
new sc,seq,linha,tabParametro,tabError,quantidade
;
kill tabParametro
set seq="",quantidade=0
for  set seq=$order(^mtempWDOMTESTEPMP110CHECK(term,41,1,seq)) quit:seq=""  do
. set linha=$get(^mtempWDOMTESTEPMP110(term,seq))
. quit:linha=""
. if +$piece(linha,Z,6)<1 quit
. set quantidade=quantidade+1
. set tabParametro(quantidade)=codEmpresa_Z_linha
if 'quantidade quit $$$ERROR(10000,"Selecione os itens para imprimir!")
;
quit $$PrintTagList^%CSW1TAG("EtiquetaIdProduto",.tabParametro,.tabError)
;
; Regra do PrintTagList: uma etiqueta por cópia de cada item selecionado
; tabParametro(n) = empresa^tipo^documento^item^descrição^qtde^qtdeEtiquetas^controle^produto
;
; do ObterDadosEtiqueta^WDOMTESTEPMP110RG(.tabParametro,.tabEtiqueta)
ObterDadosEtiqueta(tabParametro,tabEtiqueta)	;
$$$VAR
new n,i,seq,linha,qtdEtiquetas
;
kill tabEtiqueta
set (n,seq)=""
for  set n=$order(tabParametro(n)) quit:n=""  do
. set linha=tabParametro(n)
. set qtdEtiquetas=+$piece(linha,Z,7)
. for i=1:1:qtdEtiquetas do
. . set seq=seq+1
. . set tabEtiqueta(seq)="EtiquetaIdProduto"
. . set tabEtiqueta(seq,1,"tipoDocumento")=$piece(linha,Z,2)
. . set tabEtiqueta(seq,1,"documento")=$piece(linha,Z,3)
. . set tabEtiqueta(seq,1,"item")=$piece(linha,Z,4)
. . set tabEtiqueta(seq,1,"codProduto")=$piece(linha,Z,9)
. . set tabEtiqueta(seq,1,"descProduto")=$extract($piece($piece(linha,Z,5)," - ",2,99),1,40)
. . set tabEtiqueta(seq,1,"quantidade")=$$QtdePorEtiqueta($piece(linha,Z,6),qtdEtiquetas)
. . set tabEtiqueta(seq,1,"controle")=$piece(linha,Z,8)
. . set tabEtiqueta(seq,1,"etiqueta")=i_"/"_qtdEtiquetas
;
quit
